/**
 * Optimized Next.js Configuration for id
 * Generated by CODAI Build Process Optimizer
 * 
 * Features:
 * - Advanced webpack optimizations
 * - Code splitting and tree shaking
 * - Bundle analysis integration
 * - Performance monitoring
 * - Cache optimization
 * - Production-ready settings
 */

const path = require('path');
const { BundleAnalyzerPlugin } = require('webpack-bundle-analyzer');
const SpeedMeasurePlugin = require('speed-measure-webpack-plugin');
const CompressionPlugin = require('compression-webpack-plugin');

// Environment-based configuration
const isDev = process.env.NODE_ENV === 'development';
const isProduction = process.env.NODE_ENV === 'production';
const enableAnalyzer = process.env.ANALYZE === 'true';
const enableSpeedMeasure = process.env.SPEED_MEASURE === 'true';

/** @type {import('next').NextConfig} */
const nextConfig = {
    // Output configuration
    output: 'standalone',
    
    // Build optimization
    swcMinify: true,
    poweredByHeader: false,
    
    // TypeScript and ESLint
    typescript: {
        ignoreBuildErrors: false,
    },
    eslint: {
        ignoreDuringBuilds: false,
        dirs: ['pages', 'components', 'lib', 'src'],
    },
    
    // Compiler optimizations
    compiler: {
        removeConsole: isProduction ? {
            exclude: ['error', 'warn'],
        } : false,
        styledComponents: true,
    },
    
    // Image optimization
    images: {
        formats: ['image/webp', 'image/avif'],
        minimumCacheTTL: 60 * 60 * 24 * 7, // 7 days
        deviceSizes: [640, 750, 828, 1080, 1200, 1920, 2048, 3840],
        imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
    },
    
    // Experimental features
    experimental: {
        // Package import optimizations
        optimizePackageImports: [
            'lucide-react',
            'framer-motion',
            '@radix-ui/react-dialog',
            '@radix-ui/react-dropdown-menu',
            '@radix-ui/react-tooltip',
            '@radix-ui/react-toast',
            'recharts',
            'zustand',
            'react-i18next',
            'i18next'
        ],
        
        // Modern bundling
        esmExternals: true,
        
        // Performance optimizations
        webVitalsAttribution: ['CLS', 'LCP'],
        
        // Turbo configuration
        turbo: {
            rules: {
                '*.svg': {
                    loaders: ['@svgr/webpack'],
                    as: '*.js'
                }
            }
        }
    },
    
    // Webpack configuration
    webpack: (config, { buildId, dev, isServer, defaultLoaders, webpack }) => {
        // Speed measurement (development only)
        if (enableSpeedMeasure && !isServer) {
            const smp = new SpeedMeasurePlugin();
            config = smp.wrap(config);
        }
        
        // Bundle analyzer
        if (enableAnalyzer && !isServer) {
            config.plugins.push(
                new BundleAnalyzerPlugin({
                    analyzerMode: 'static',
                    reportFilename: `../analysis/${appName}-bundle-report.html`,
                    openAnalyzer: false,
                    generateStatsFile: true,
                    statsFilename: `../analysis/${appName}-bundle-stats.json`,
                })
            );
        }
        
        // Production optimizations
        if (isProduction && !isServer) {
            // Compression
            config.plugins.push(
                new CompressionPlugin({
                    algorithm: 'gzip',
                    test: /\.(js|css|html|svg)$/,
                    threshold: 8192,
                    minRatio: 0.8,
                })
            );
            
            // Advanced code splitting
            config.optimization = {
                ...config.optimization,
                moduleIds: 'deterministic',
                runtimeChunk: 'single',
                splitChunks: {
                    chunks: 'all',
                    cacheGroups: {
                        // Vendor chunks
                        vendor: {
                            test: /[\\/]node_modules[\\/]/,
                            name: 'vendors',
                            priority: 10,
                            reuseExistingChunk: true,
                        },
                        
                        // React chunks
                        react: {
                            test: /[\\/]node_modules[\\/](react|react-dom)[\\/]/,
                            name: 'react',
                            priority: 20,
                            reuseExistingChunk: true,
                        },
                        
                        // UI library chunks
                        ui: {
                            test: /[\\/](components|ui)[\\/]|[\\/]node_modules[\\/](@radix-ui|lucide-react)[\\/]/,
                            name: 'ui',
                            priority: 15,
                            reuseExistingChunk: true,
                        },
                        
                        // i18n chunks
                        i18n: {
                            test: /[\\/]node_modules[\\/](i18next|react-i18next)[\\/]/,
                            name: 'i18n',
                            priority: 12,
                            reuseExistingChunk: true,
                        },
                        
                        // Animation chunks
                        animations: {
                            test: /[\\/]node_modules[\\/]framer-motion[\\/]/,
                            name: 'animations',
                            priority: 8,
                            reuseExistingChunk: true,
                        },
                        
                        // Common chunks
                        common: {
                            name: 'common',
                            minChunks: 2,
                            priority: 5,
                            reuseExistingChunk: true,
                        },
                    },
                },
            };
        }
        
        // Resolve aliases
        config.resolve.alias = {
            ...config.resolve.alias,
            '@': path.resolve(__dirname),
            '@/components': path.resolve(__dirname, 'components'),
            '@/lib': path.resolve(__dirname, 'lib'),
            '@/hooks': path.resolve(__dirname, 'hooks'),
            '@/ui': path.resolve(__dirname, 'lib/ui'),
        };
        
        // Tree shaking optimization
        config.optimization = {
            ...config.optimization,
            usedExports: true,
            sideEffects: false,
        };
        
        // Module rules optimization
        config.module.rules.push({
            test: /\.svg$/,
            use: ['@svgr/webpack'],
        });
        
        return config;
    },
    
    // Security headers
    async headers() {
        return [
            {
                source: '/(.*)',
                headers: [
                    {
                        key: 'X-Frame-Options',
                        value: 'DENY',
                    },
                    {
                        key: 'X-Content-Type-Options',
                        value: 'nosniff',
                    },
                    {
                        key: 'Referrer-Policy',
                        value: 'origin-when-cross-origin',
                    },
                    {
                        key: 'X-XSS-Protection',
                        value: '1; mode=block',
                    },
                ],
            },
        ];
    },
    
    // Redirects for optimization
    async redirects() {
        return [];
    },
    
    // Rewrites for optimization
    async rewrites() {
        return [];
    },
};

module.exports = nextConfig;
